CREATE TABLE `washing_payment_allocations` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `washing_payment_id` bigint(20) UNSIGNED NOT NULL,
  `allocatable_type` varchar(255) NOT NULL,
  `allocatable_id` bigint(20) UNSIGNED NOT NULL,
  `allocated_amount` decimal(18,4) NOT NULL,
  `exchange_rate` decimal(15,6) NOT NULL DEFAULT 1.000000,
  `base_allocated_amount` decimal(18,4) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

